CREATE SET TABLE MDP01_META.META_DATABASE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      database_id INTEGER NOT NULL,      database_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      layer_id INTEGER NOT NULL,      owner_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      creator_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      permanent_space DECIMAL(18,0),      spool_space DECIMAL(18,0),      temp_space DECIMAL(18,0),      comment_string VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      create_timestamp TIMESTAMP(6),      last_alter_timestamp TIMESTAMP(6),      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( database_id )UNIQUE INDEX ( database_name );